mat3 mat = mat3(
    .447, .898, .973,
    .306, .310,  .776,
    .569, .427, .188);

void mainImage(out vec4 col, in vec2 pos) {
    vec3 vals = texelFetch(iChannel0, ivec2(pos), 0).xyz;
    col = vec4(vals * mat, 1.);
}

#define D 1.
#define DT .25
#define A .75

vec3 hash(vec3 p) {
    // Hash function from Dave Hoskins
	vec3 p3 = fract(p * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yxz+33.33);
    return fract((p3.xxy+p3.yzz)*p3.zyx);
}

vec3 getVal(vec2 p) {
    // Texture sampling
    p = mod(p, iResolution.xy);
    return texelFetch(iChannel0, ivec2(p), 0).xyz;
}

vec3 laplace(vec2 p) {
    // Laplace operator
    vec3 k = -getVal(p);
    k += 0.2 * getVal(p + vec2(1., 0.));
    k += 0.2 * getVal(p + vec2(-1., 0.));
    k += 0.2 * getVal(p + vec2(0., 1.));
    k += 0.2 * getVal(p + vec2(0., -1.));
    k += 0.05 * getVal(p + vec2(.5));
    k += 0.05 * getVal(p + vec2(-.5, .5));
    k += 0.05 * getVal(p + vec2(.5, -.5));
    k += 0.05 * getVal(p + vec2(-.5));
    return k;
}

void mainImage(out vec4 st, in vec2 pos) {
    // Return noise
    bool isDrawing = (distance(pos, iMouse.xy) < 20. && iMouse.z > 0.);
    if (iFrame < 3 || isDrawing) {
        st = vec4(hash(vec3(pos, iTime)), 1.);
        return;
    }

    // Get new point
    vec3 vals = texelFetch(iChannel0, ivec2(pos), 0).xyz;
    vec3 lap = laplace(pos);
    float rho = 1. - dot(vals, vec3(1.));
    vec3 diff = D * lap + vals * (rho - A * vals.yzx);

    st = vec4(vals + DT * diff, 1.);
}
